// Normaliza un design de MakerWorld al shape que /api/products/sync espera.
// MakerWorld usa keys 'BY', 'BY-SA', 'BY-NC-SA' (sin prefijo 'CC ') y 'Standard Digital File License' para comercial.
const LICENSE_MAP = {
  'BY': 'CC-BY',
  'BY-SA': 'CC-BY-SA',
  'BY-NC': 'CC-BY-NC',
  'BY-NC-SA': 'CC-BY-NC',
  'BY-ND': 'CC-BY',
  'BY-NC-ND': 'CC-BY-NC',
  'CC0': 'CC0',
  'Standard Digital File License': 'commercial',
};

return items.map(({ json: d }) => {
  const rawLicense = (d.license || '').trim();
  const licenseType = LICENSE_MAP[rawLicense] || 'unknown';
  const author = d.designCreator?.name || 'Unknown';
  const externalId = String(d.id ?? '');
  const slug = d.slug || externalId;
  return {
    json: {
      externalId,
      source: 'MAKERWORLD',
      sourceUrl: `https://makerworld.com/en/models/${slug}`,
      title: d.titleTranslated || d.title || 'Untitled',
      description: '',
      imageUrl: d.cover || d.coverPortrait || d.coverLandscape || null,
      licenseType,
      licenseAttribution: `${author} — via MakerWorld`,
      category: (Array.isArray(d.tags) && d.tags[0]) || null,
      trendScore: Math.round(d.hotScore ?? d.likeCount ?? 0),
      price: null,
      stock: null,
      provider: 'LOCAL',
    },
  };
});

// Calcula precio usando la formula de PrintCost3DCalculator.
// Fuente: components/PrintCost3DCalculator.vue defaults: filament $400/kg, waste 5%, kwh $4.5, watts fallback 100W.
// Margen 300% por decision del owner (2026-07-28).
const FILAMENT_PRICE_PER_KG = 400;
const WASTE_PCT = 5;
const KWH_PRICE = 4.5;
const WATTS = 100;
const MARGIN_PCT = 300;

return items.map(({ json }) => {
  // json aqui es la respuesta del detail (item enriquecido con lo que traia antes).
  // n8n merge: los datos de Normalize NO estan aqui; hay que sacar del detail mismo lo minimo o pasar por otro camino.
  const plate = json?.instances?.[0]?.extention?.modelInfo?.plates?.[0];
  const grams = Number(plate?.weight) || 0;
  const seconds = Number(plate?.prediction) || 0;
  const hours = seconds / 3600;

  let price = null;
  if (grams > 0 && hours > 0) {
    const effectiveGrams = grams * (1 + WASTE_PCT / 100);
    const filament = (effectiveGrams / 1000) * FILAMENT_PRICE_PER_KG;
    const electricity = hours * (WATTS / 1000) * KWH_PRICE;
    const subtotal = filament + electricity;
    price = Math.round(subtotal * (1 + MARGIN_PCT / 100));
  }

  return { json: { detail: json, computed: { grams, hours, price } } };
});

// Combina lo normalizado (paso 'Drop unknown licenses') con el precio calculado.
// n8n pairing: cada item aqui corresponde 1:1 con el output de Drop (misma posicion),
// entonces usamos $('Drop unknown licenses').all() para recuperar el shape /sync.
const normalized = $('Drop unknown licenses').all();
const products = items.map((item, i) => {
  const n = normalized[i]?.json || {};
  const price = item?.json?.computed?.price;
  return { ...n, price: price ?? null };
});
return [{ json: { products } }];
